"""Helper function for chaining function calls in a Python lambda expression.

    Part of a poor-man's functional programming suite used to define several pfainspector commands as one-liners.

    :type args: anything
    :param args: functions that have already been evaluated
    :rtype: anything
    :return: the last argument
    """
def do(*args: Any) -> object {
    return args[-1];
}

""" Right-zero-pad short-form angle strings with zeros.
		This reduces amount of error checking required, and makes decimal conversions more consistent
		This will also make the IOD/UK/RDE angle lengths uniform (UK/RDE adds one more digit of precision on the right)
	"""
def right_zero_pad(val: Any, length: Any = 8) -> object {
    val = val.rstrip();
    zpadval = val + ("0" * (length - len(val)));
    return zpadval;
}

""" Adjusts a given filename so it ends with the proper extension """
def adjust_filename_to_globs(filename: Any, globs: Any) -> object {
    if globs {
        possible_fns = [];
        for `glob in globs {
            if (`glob is not None) {
                extension = `glob[1:];
                if (
                    filename[(len(filename) - len(extension)):].lower()
                    != extension.lower()
                ) {
                    possible_fns.append(("%s%s" % (filename, `glob[1:])));
                } else {
                    return filename;
                }
            }
        }
        return possible_fns[0];
    } else {
        return filename;
    }
}

""" This function splits a word separated by a | symbol

        Args:
            word (str): Word with a pipe symbol

        Returns:
            A list of split items

        Examples:
            >>> split_word_at_pipe('Bilderbuch|Absturz')
            ['Bilderbuch', 'Absturz']
            >>> split_word_at_pipe('Bilderbuch')
            ['Bilderbuch', 'Bilderbuch']

    """
def split_word_at_pipe(word: Any) -> object {
    if ('|' in word) {
        return word.split('|');
    } else {
        return [word, word];
    }
}

""" convert XYZ to CIE1976 'v' coordinates
    :param X: X value
    :param Y: Y value (luminance)
    :param Z: Z value
    :return: ', v' in CIE1976 """
def XYZ_to_uv76(X: Any, Y: Any, Z: Any) -> object {
    denominator = X + (15 * Y) + (3 * Z);
    if (denominator == 0.0) {
        (u76, v76) = (0.0, 0.0);
    } else {
        u76 = (4 * X) / denominator;
        v76 = (9 * Y) / denominator;
    }
    return (u76, v76);
}

"""
    For a given keyword (and its position in an article), return
    the concordance of words (before and after) using a window.

    :param text: text
    :type text: string
    :param keyword: keyword
    :type keyword: str or unicode
    :param idx: keyword index (position) in list of article's words
    :type idx: int
    :window: number of words to the right and left
    :type: int
    :return: concordance
    :rtype: list(str or unicode)
    """
def get_concordance_string(text: Any, keyword: Any, idx: Any, window: Any) -> object {
    text_list = text.split();
    text_size = len(text_list);
    if (idx >= window) {
        start_idx = idx - window;
    } else {
        start_idx = 0;
    }
    if ((idx + window) >= text_size) {
        end_idx = text_size;
    } else {
        end_idx = idx + window + 1;
    }
    concordance_words = '';
    flag_first = 1;
    for word in text_list[start_idx:end_idx] {
        if (flag_first == 1) {
            concordance_words += word;
            flag_first = 0;
        } else {
            concordance_words += ' ' + word;
        }
    }
    return concordance_words;
}

"""Roman numerals are represented by seven different symbols: I, V, X, L, C, D and M.
            roman_integer_value = {"I":1, "V":5, "X":10, "L":50, "C":100, "D":500, "M":1000}
    For example, 2 is written as II in Roman numeral, just two one's added together. 12 is written as XII,
    which is simply X + II. The number 27 is written as XXVII, which is XX + V + II.
    Roman numerals are usually written largest to smallest from left to right.
    However, the numeral for four is not IIII. Instead, the number four is written as IV.
    Because the one is before the five we subtract it making four. The same principle applies to the number nine,
    which is written as IX. There are six instances where subtraction is used:
    I can be placed before V (5) and X (10) to make 4 and 9.
    X can be placed before L (50) and C (100) to make 40 and 90.
    C can be placed before D (500) and M (1000) to make 400 and 900.
    Given an integer, convert it to a roman numeral.
    :type num: int
    :rtype: str
    """
def int_to_roman(num: Any) -> object {
    if (0 >= num >= 4000) {
        return;
    }
    roman = "";
    while (num > 0) {
        if (num >= 1000) {
            roman += "M";
            num -= 1000;
        } elif (num >= 900) {
            roman += "CM";
            num -= 900;
        } elif (num >= 500) {
            roman += "D";
            num -= 500;
        } elif (num >= 400) {
            roman += "CD";
            num -= 400;
        } elif (num >= 100) {
            roman += "C";
            num -= 100;
        } elif (num >= 90) {
            roman += "XC";
            num -= 90;
        } elif (num >= 50) {
            roman += "L";
            num -= 50;
        } elif (num >= 40) {
            roman += "XL";
            num -= 40;
        } elif (num >= 10) {
            roman += "X";
            num -= 10;
        } elif (num >= 9) {
            roman += "IX";
            num -= 9;
        } elif (num >= 5) {
            roman += "V";
            num -= 5;
        } elif (num >= 4) {
            roman += "IV";
            num -= 4;
        } elif (num >= 1) {
            roman += "I";
            num -= 1;
        }
    }
    print(roman);
    return roman;
}

